function M.summary(result)
  if #result.groups == 0 then
    return ("no structural duplicates among %d functions of %d+ nodes"):format(
      result.considered,
      result.min_size
    )
  end
  return ("%d duplicate group%s covering %d functions"):format(
    #result.groups,
    #result.groups == 1 and "" or "s",
    result.functions
  )
end

